// Check the art direction before it reaches the image model, because a prompt
// that asks for lettering produces an unusable image and still costs money.
const ctx = $('Build Art Prompt').first().json;
const art = agentJson($input.first().json, 'Art agent');
require_(art, ['cover_prompt', 'thumbnail_prompt'], 'The art direction');

// Words that mean "draw type". Checked against the prompt we are about to
// send, not against the picture we get back, because by then it is paid for.
const TYPE_WORDS = /\b(text|typography|lettering|letters?|words?|title|caption|label(?:s|led)?|font|handwriting|calligraphy|monogram|signature|numbers?|dates?|calendar grid|planner page|mockup)\b/i;
const NEGATED = /\b(no|without|avoid|never|free of|excluding)\b[^.]{0,40}$/i;

const check = (prompt, where) => {
  const value = String(prompt || '');
  if (!value.trim()) throw new Error(`${where} is empty`);
  for (const sentence of value.split(/(?<=[.;])\s+/)) {
    const hit = sentence.match(TYPE_WORDS);
    if (!hit) continue;
    // "no text, no lettering" is the instruction we want, not a violation.
    if (NEGATED.test(sentence.slice(0, hit.index))) continue;
    throw new Error(
      `${where} asks the image model for type, which it renders badly and which ` +
      `gets the product rejected: "${sentence.trim().slice(0, 120)}"`);
  }
  return value.trim();
};

const sectionPrompts = asArray(art.section_prompts);
const wanted = ctx.section_art_count;
while (sectionPrompts.length < wanted) {
  sectionPrompts.push(sectionPrompts[sectionPrompts.length - 1] || art.cover_prompt);
}

const suffix = ' No text, no letters, no numbers, no words anywhere in the image.';
return [{
  json: {
    ...ctx,
    stage: 'art-ready',
    art: {
      palette: String(art.palette || ''),
      cover_prompt: check(art.cover_prompt, 'cover_prompt') + suffix,
      thumbnail_prompt: check(art.thumbnail_prompt, 'thumbnail_prompt') + suffix,
      section_prompts: sectionPrompts.slice(0, wanted)
        .map((p, i) => check(p, `section_prompts[${i}]`) + suffix),
    },
  },
}];

// One item per image to generate, so the loop below can be a plain loop and
// the cost is visible as a row count rather than hidden in a branch.
const ctx = $('Parse Art').first().json;
const cfg = $('Planner Config').first().json.cfg;

const jobs = [
  { role: 'cover', prompt: ctx.art.cover_prompt, size: '1024x1536',
    quality: cfg.IMAGE_QUALITY_COVER || 'high' },
  { role: 'thumbnail', prompt: ctx.art.thumbnail_prompt, size: '1024x1024',
    quality: cfg.IMAGE_QUALITY_THUMB || 'low' },
];
ctx.art.section_prompts.forEach((prompt, index) => {
  jobs.push({ role: `section_${index + 1}`, prompt, size: '1024x1536',
              quality: cfg.IMAGE_QUALITY_SECTION || 'medium' });
});

return jobs.map((job) => ({ json: { ...job, run_id: ctx.run_id, dry_run: ctx.dry_run } }));

// Rehearsal mode: hand back a real (tiny) JPEG so every later step - including
// the PDF writer - runs exactly as it would on a paid run.
const job = $input.first().json;
return [{ json: { ...job, b64: '/9j/4AAQSkZJRgABAQEAYABgAAD/2wBDAAgGBgcGBQgHBwcJCQgKDBQNDAsLDBkSEw8UHRofHh0aHBwgJC4nICIsIxwcKDcpLDAxNDQ0Hyc5PTgyPC4zNDL/wAALCAABAAEBAREA/8QAFAABAAAAAAAAAAAAAAAAAAAACf/EABQQAQAAAAAAAAAAAAAAAAAAAAD/2gAIAQEAAD8AKp//2Q==', dry: true } }];

// The image endpoint answers with data[0].b64_json. Anything else is an error
// worth surfacing here, next to the job that caused it.
const job = $('Loop Images').first().json;
const response = $input.first().json;
const b64 = response && response.data && response.data[0] && response.data[0].b64_json;
if (!b64) {
  throw new Error(`No image came back for "${job.role}": ` +
                  JSON.stringify(response).slice(0, 300));
}
return [{ json: { ...job, b64 } }];

// Fold every generated image into one item keyed by role.
const ctx = $('Parse Art').first().json;
const images = {};
for (const item of $input.all()) {
  if (item.json && item.json.role && item.json.b64) images[item.json.role] = item.json.b64;
}
const expected = ['cover', 'thumbnail',
  ...ctx.art.section_prompts.map((_, i) => `section_${i + 1}`)];
const missing = expected.filter((role) => !images[role]);
if (missing.length) throw new Error(`Missing generated images: ${missing.join(', ')}`);

return [{ json: { ...ctx, stage: 'art-done', images } }];

// ---------------------------------------------------------------------------
// Minimal PDF 1.4 writer (no external dependencies).
// ---------------------------------------------------------------------------
const PDF_FONT = { regular: 'F1', bold: 'F2' };

// Strip anything Helvetica/WinAnsi cannot show, then escape PDF string syntax.
function pdfEscape(text) {
  return String(text === undefined || text === null ? '' : text)
    .replace(/[‘’]/g, "'")
    .replace(/[“”]/g, '"')
    .replace(/[–—]/g, '-')
    .replace(/…/g, '...')
    .replace(/[^\x20-\x7E\xA1-\xFF]/g, '')
    .replace(/\\/g, '\\\\')
    .replace(/\(/g, '\\(')
    .replace(/\)/g, '\\)');
}

// Read width/height/components out of a JPEG SOF marker.
function jpegInfo(buffer) {
  let i = 2;
  while (i < buffer.length - 9) {
    if (buffer[i] !== 0xff) { i += 1; continue; }
    const marker = buffer[i + 1];
    if (marker === 0xd8 || marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
      i += 2;
      continue;
    }
    const length = buffer.readUInt16BE(i + 2);
    const isSOF = marker >= 0xc0 && marker <= 0xcf &&
      marker !== 0xc4 && marker !== 0xc8 && marker !== 0xcc;
    if (isSOF) {
      return {
        height: buffer.readUInt16BE(i + 5),
        width: buffer.readUInt16BE(i + 7),
        components: buffer[i + 9],
      };
    }
    i += 2 + length;
  }
  return { width: 1024, height: 1024, components: 3 };
}

// Greedy word wrap. Helvetica averages ~0.5em per character, which is accurate
// enough for body copy at 10-12pt.
function wrapText(text, fontSize, usableWidth) {
  const maxChars = Math.max(20, Math.floor(usableWidth / (fontSize * 0.5)));
  const out = [];
  for (const rawLine of String(text).split('\n')) {
    let line = '';
    for (const word of rawLine.split(/\s+/)) {
      if (!word) continue;
      if (!line.length) { line = word; continue; }
      if ((line + ' ' + word).length <= maxChars) { line += ' ' + word; }
      else { out.push(line); line = word; }
    }
    out.push(line);
  }
  return out;
}

// A field the model answered with a bare string still typesets as one line,
// and a missing one produces nothing rather than the word "undefined".
function asLines(value) {
  if (Array.isArray(value)) return value.map((v) => String(v === null || v === undefined ? '' : v));
  if (value === undefined || value === null || value === '') return [];
  return [String(value)];
}

// ---------------------------------------------------------------------------
// Calendar geometry. A language model cannot lay out February; Date can.
// ---------------------------------------------------------------------------
const WEEKDAYS_SUN = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

function weekdayHeaders(startsMonday) {
  return startsMonday
    ? WEEKDAYS_SUN.slice(1).concat(WEEKDAYS_SUN.slice(0, 1))
    : WEEKDAYS_SUN.slice();
}

// Returns six rows of seven cells. A dated planner gets real day numbers; an
// undated one gets empty boxes the buyer fills in, which is what makes the
// product evergreen instead of worthless every January.
function monthMatrix(year, month, startsMonday) {
  const rows = [[], [], [], [], [], []];
  if (!year) {
    for (const row of rows) { for (let i = 0; i < 7; i += 1) row.push(0); }
    return { rows, dated: false, days: 0 };
  }
  const days = new Date(Date.UTC(year, month, 0)).getUTCDate();
  let lead = new Date(Date.UTC(year, month - 1, 1)).getUTCDay();
  if (startsMonday) lead = (lead + 6) % 7;
  const cells = [];
  for (let i = 0; i < lead; i += 1) cells.push(null);
  for (let d = 1; d <= days; d += 1) cells.push(d);
  while (cells.length < 42) cells.push(null);
  for (let r = 0; r < 6; r += 1) rows[r] = cells.slice(r * 7, r * 7 + 7);
  return { rows, dated: true, days };
}

function buildPdf(spec) {
  const PW = spec.width || 595.28;   // A4 portrait by default
  const PH = spec.height || 841.89;
  const margin = spec.margin || 56;
  const bodySize = spec.body_size || 11;
  const leading = Math.round(bodySize * 1.5);

  // Clickable month/section tabs down the right edge. This is what separates a
  // $5 printable from a $20 digital planner: the file becomes something you
  // navigate rather than scroll. The strip steals width from the body column.
  const tabs = Array.isArray(spec.tabs)
    ? spec.tabs.filter((t) => t && t.anchor).slice(0, 16)
    : [];
  const TAB_W = tabs.length ? (spec.tab_width || 26) : 0;
  const usableWidth = PW - margin * 2 - TAB_W;
  const contentRight = PW - margin - TAB_W;

  // Object ids 1-5 are reserved: catalog, page tree, 2 fonts, document info.
  const objects = [null, null, null, null, null];
  const push = (content) => { objects.push(content); return objects.length; };
  const pageIds = [];

  // A link can point at a page that has not been written yet - a January tab
  // on the cover, say - so pages are reserved now and serialised at the end,
  // once every anchor has a page to resolve to.
  const pageMeta = [];
  const anchors = {};

  const addPage = (contentStream, extraResources) => {
    const contentId = push(
      `<< /Length ${Buffer.byteLength(contentStream, 'latin1')} >>\n` +
      `stream\n${contentStream}\nendstream`
    );
    const id = push('');
    pageIds.push(id);
    const meta = { id, contentId, resources: extraResources || null, links: [] };
    pageMeta.push(meta);
    return meta;
  };

  const footer = (label) => {
    if (!label) return '';
    return `BT /${PDF_FONT.regular} 8 Tf 0.45 0.45 0.45 rg ` +
      `${margin} ${(margin / 2).toFixed(2)} Td (${pdfEscape(label)}) Tj ET 0 0 0 rg\n`;
  };

  // Returns the drawing commands plus the link rectangles they imply. Links
  // are collected rather than attached because the page object does not exist
  // until its content stream has been measured.
  const tabStrip = (activeAnchor) => {
    if (!tabs.length) return { stream: '', links: [] };
    const top = PH - margin;
    const slot = (top - margin) / tabs.length;
    const height = Math.min(slot - 3, 96);
    const links = [];
    let stream = '';
    tabs.forEach((tab, index) => {
      const y = top - slot * index - height;
      const x = PW - TAB_W;
      const active = activeAnchor && tab.anchor === activeAnchor;
      const shade = active ? '0.25' : '0.88';
      stream += `${shade} ${shade} ${shade} rg ` +
        `${x.toFixed(2)} ${y.toFixed(2)} ${TAB_W.toFixed(2)} ${height.toFixed(2)} re f\n`;
      // A 90-degree text matrix so the label reads bottom-to-top in the tab.
      stream += `BT /${PDF_FONT.bold} 8 Tf ${active ? '1 1 1' : '0.2 0.2 0.2'} rg ` +
        `0 1 -1 0 ${(x + TAB_W / 2 + 3).toFixed(2)} ${(y + 7).toFixed(2)} Tm ` +
        `(${pdfEscape(String(tab.label || '').slice(0, 14))}) Tj ET 0 0 0 rg\n`;
      links.push({ anchor: tab.anchor, rect: [x, y, x + TAB_W, y + height] });
    });
    return { stream, links };
  };

  // ---- drawing primitives ------------------------------------------------
  const RULE = (shade) => `${shade} ${shade} ${shade} RG`;

  const line = (x1, y1, x2, y2, width, shade) =>
    `${width} w ${RULE(shade)} ${x1.toFixed(2)} ${y1.toFixed(2)} m ` +
    `${x2.toFixed(2)} ${y2.toFixed(2)} l S 0 0 0 RG\n`;

  const label = (text, x, y, size, font, shade) =>
    `BT /${font} ${size} Tf ${shade} ${shade} ${shade} rg ${x.toFixed(2)} ` +
    `${y.toFixed(2)} Td (${pdfEscape(text)}) Tj ET 0 0 0 rg\n`;

  // Right-aligned text needs the string's width, and Helvetica's real widths
  // are not uniform. 0.5em is the same approximation wrapText uses; a day
  // number is two characters, so the error is under a point.
  const labelRight = (text, x, y, size, font, shade) =>
    label(text, x - String(text).length * size * 0.5, y, size, font, shade);

  // A table drawn as lines, not as text: column rules, row rules, an optional
  // shaded header band. Everything with a grid on the page goes through here.
  // ``first_col_width`` widens column 0 for row labels. Without it a habit
  // called "Lights out by 11" ran straight through the column rule and into
  // Monday.
  const table = (x, y, w, h, cols, rows, opts) => {
    const options = opts || {};
    const firstW = options.first_col_width || 0;
    const colW = firstW ? (w - firstW) / Math.max(1, cols - 1) : w / cols;
    const colX = (index) => (firstW
      ? (index === 0 ? x : x + firstW + colW * (index - 1))
      : x + colW * index);
    const headerH = options.header_height || 0;
    const bodyY = y - headerH;
    const rowH = (h - headerH) / rows;
    let stream = '';

    if (headerH && options.header_shade !== undefined) {
      const s = options.header_shade;
      stream += `${s} ${s} ${s} rg ${x.toFixed(2)} ${bodyY.toFixed(2)} ` +
        `${w.toFixed(2)} ${headerH.toFixed(2)} re f\n`;
    }
    if (Array.isArray(options.headers)) {
      options.headers.forEach((text, index) => {
        stream += label(text, colX(index) + 6, bodyY + headerH / 2 - 3,
                        options.header_size || 8, PDF_FONT.bold, 0.25);
      });
    }
    for (let r = 0; r <= rows; r += 1) {
      const ly = bodyY - rowH * r;
      stream += line(x, ly, x + w, ly, 0.6, r === 0 ? 0.55 : 0.82);
    }
    if (headerH) stream += line(x, y, x + w, y, 0.6, 0.55);
    for (let c = 0; c <= cols; c += 1) {
      const lx = c === cols ? x + w : colX(c);
      stream += line(lx, y, lx, bodyY - rowH * rows, 0.6, 0.82);
    }
    return { stream, colW, rowH, bodyY, firstW: firstW || colW, colX };
  };

  // A table of contents whose rows jump to the page they name. Rows that do
  // not fit are counted, never quietly discarded: a contents list that stops
  // short is worse than none at all, and it is invisible unless someone looks
  // at the last page.
  let droppedRows = 0;
  const indexBlock = (entries, startY) => {
    const links = [];
    let stream = '';
    let y = startY;
    for (const entry of entries) {
      if (!entry || !entry.anchor) continue;
      if (y < margin + leading) { droppedRows += 1; continue; }
      stream += `BT /${PDF_FONT.regular} ${bodySize} Tf ${margin} ${y.toFixed(2)} Td ` +
        `(${pdfEscape(entry.label)}) Tj ET\n`;
      stream += `[1 3] 0 d 0.75 0.75 0.75 RG 0.6 w ` +
        `${(margin + 8).toFixed(2)} ${(y - 3).toFixed(2)} m ` +
        `${contentRight.toFixed(2)} ${(y - 3).toFixed(2)} l S [] 0 d 0 0 0 RG\n`;
      links.push({
        anchor: entry.anchor,
        rect: [margin - 4, y - 5, contentRight, y + bodySize + 2],
      });
      y -= leading * 1.7;
    }
    return { stream, links };
  };

  for (const page of spec.pages || []) {
    // An anchor names the first page emitted for this spec entry, so a link
    // lands on the section opener even when the section spills over.
    const anchorSlot = pageIds.length;
    if (page.anchor) anchors[page.anchor] = anchorSlot;

    // ---- image page: fit the JPEG inside the page, centred -----------------
    if (page.type === 'image' && page.jpeg_base64) {
      const data = Buffer.from(page.jpeg_base64, 'base64');
      const info = jpegInfo(data);
      const bleed = page.full_bleed ? 0 : margin / 2;
      // A full-bleed page keeps the whole sheet; anything else leaves the tab
      // gutter clear so the strip never sits on top of the artwork.
      const gutter = page.full_bleed ? 0 : TAB_W;
      const scale = Math.min(
        (PW - gutter - bleed * 2) / info.width,
        (PH - bleed * 2) / info.height
      );
      const w = info.width * scale;
      const h = info.height * scale;
      const x = (PW - gutter - w) / 2;
      const y = (PH - h) / 2;
      const imageId = push(Buffer.concat([
        Buffer.from(
          `<< /Type /XObject /Subtype /Image /Width ${info.width} /Height ${info.height}` +
          ` /ColorSpace ${info.components === 1 ? '/DeviceGray' : '/DeviceRGB'}` +
          ` /BitsPerComponent 8 /Filter /DCTDecode /Length ${data.length} >>\nstream\n`,
          'latin1'
        ),
        data,
        Buffer.from('\nendstream', 'latin1'),
      ]));
      let stream = `q ${w.toFixed(2)} 0 0 ${h.toFixed(2)} ${x.toFixed(2)} ${y.toFixed(2)} cm /Im0 Do Q\n`;
      if (page.caption) {
        stream += `BT /${PDF_FONT.regular} 10 Tf ${margin} ${(y - 18).toFixed(2)} Td ` +
          `(${pdfEscape(page.caption)}) Tj ET\n`;
      }
      stream += footer(page.footer);
      const strip = page.full_bleed ? { stream: '', links: [] } : tabStrip(page.anchor);
      const meta = addPage(stream + strip.stream, `/XObject << /Im0 ${imageId} 0 R >>`);
      for (const link of strip.links) meta.links.push(link);
      continue;
    }

    // ---- month page: calendar grid plus a side column ----------------------
    if (page.type === 'month') {
      const titleY = PH - margin - 22;
      let stream = label(page.title || 'Month', margin, titleY, 24, PDF_FONT.bold, 0);
      if (page.subtitle) {
        stream += label(page.subtitle, margin, titleY - 18, 10, PDF_FONT.regular, 0.4);
      }

      // The side column carries the writing prompts the model produced. The
      // calendar keeps whatever is left, so a longer prompt never squeezes a
      // week off the page - the split is fixed.
      const sideW = page.side_lines && page.side_lines.length ? 150 : 0;
      const gridW = contentRight - margin - (sideW ? sideW + 14 : 0);
      const gridTop = titleY - 40;
      const gridH = gridTop - margin - 18;

      const matrix = monthMatrix(
        page.year ? Number(page.year) : null,
        Number(page.month_number) || 1,
        page.week_starts_monday !== false
      );
      // A month that fits in five weeks gets five taller rows instead of a
      // blank strip along the bottom. Five is the floor so the twelve months
      // do not all have different-sized boxes.
      let weeks = matrix.rows.length;
      while (weeks > 5 && matrix.rows[weeks - 1].every((d) => !d)) weeks -= 1;

      const headers = weekdayHeaders(page.week_starts_monday !== false);
      const grid = table(margin, gridTop, gridW, gridH, 7, weeks, {
        headers, header_height: 18, header_shade: 0.93, header_size: 8,
      });
      stream += grid.stream;

      matrix.rows.slice(0, weeks).forEach((row, r) => {
        row.forEach((day, c) => {
          if (!day) return;
          stream += labelRight(String(day),
                               margin + grid.colW * (c + 1) - 5,
                               grid.bodyY - grid.rowH * r - 12,
                               9, PDF_FONT.regular, 0.35);
        });
      });

      if (sideW) {
        const sx = contentRight - sideW;
        let sy = gridTop;
        stream += label(page.side_title || 'This month', sx, sy, 10, PDF_FONT.bold, 0.2);
        sy -= 20;
        for (const raw of page.side_lines) {
          for (const wrapped of wrapText(raw, 9, sideW)) {
            if (sy < margin + 30) break;
            stream += label(wrapped, sx, sy, 9, PDF_FONT.regular, 0.35);
            sy -= 13;
          }
          // A ruled answer space under each prompt - the point of a planner.
          for (let i = 0; i < 2 && sy > margin + 24; i += 1) {
            sy -= 12;
            stream += line(sx, sy, sx + sideW, sy, 0.5, 0.85);
          }
          sy -= 12;
        }
      }

      stream += footer(page.footer);
      const strip = tabStrip(page.anchor);
      const meta = addPage(stream + strip.stream, null);
      for (const link of strip.links) meta.links.push(link);
      continue;
    }

    // ---- grid page: a ruled table with column headers ----------------------
    if (page.type === 'grid') {
      const titleY = PH - margin - 18;
      let stream = label(page.title || '', margin, titleY, 18, PDF_FONT.bold, 0);
      let top = titleY - 16;
      if (page.subtitle) {
        stream += label(page.subtitle, margin, top, 10, PDF_FONT.regular, 0.4);
        top -= 20;
      }
      for (const raw of asLines(page.lines)) {
        for (const wrapped of wrapText(raw, 10, contentRight - margin)) {
          stream += label(wrapped, margin, top, 10, PDF_FONT.regular, 0.3);
          top -= 15;
        }
      }
      top -= 10;

      const headers = Array.isArray(page.columns) ? page.columns : [];
      const rows = Math.max(1, Number(page.rows) || 12);
      const rowLabels = asLines(page.row_labels);
      const width = contentRight - margin;
      // A label column only needs to be wide when there are labels for it.
      const firstColW = rowLabels.length
        ? Math.min(170, Math.max(90, width * 0.28))
        : 0;
      const grid = table(margin, top, width, top - margin - 16,
                         Math.max(1, headers.length), rows, {
        headers, header_height: 20, header_shade: 0.93, header_size: 8,
        first_col_width: firstColW,
      });
      stream += grid.stream;

      // Row labels turn an empty table into a filled-in tracker: the model
      // supplies the habits, the writer supplies the boxes. Clipped to the
      // column it lives in rather than to a guessed character count.
      const labelSize = 8;
      const maxChars = Math.max(6, Math.floor((grid.firstW - 12) / (labelSize * 0.5)));
      rowLabels.forEach((text, index) => {
        if (index >= rows) return;
        stream += label(String(text).slice(0, maxChars), margin + 6,
                        grid.bodyY - grid.rowH * (index + 1) + grid.rowH / 2 - 3,
                        labelSize, PDF_FONT.regular, 0.3);
      });

      stream += footer(page.footer);
      const strip = tabStrip(page.anchor);
      const meta = addPage(stream + strip.stream, null);
      for (const link of strip.links) meta.links.push(link);
      continue;
    }

    // ---- lined page: prompts over ruled or dotted writing space ------------
    if (page.type === 'lined') {
      const titleY = PH - margin - 18;
      let stream = label(page.title || '', margin, titleY, 18, PDF_FONT.bold, 0);
      // The title needs air under it; without this the first prompt sat on
      // the title's baseline and read as a subtitle.
      let y = titleY - 30;
      if (page.subtitle) {
        stream += label(page.subtitle, margin, titleY - 16, 10, PDF_FONT.regular, 0.4);
        y = titleY - 44;
      }
      const spacing = Math.max(14, Number(page.spacing) || 26);
      const width = contentRight - margin;

      for (const prompt of asLines(page.lines)) {
        if (y < margin + spacing * 2) break;
        for (const wrapped of wrapText(prompt, 11, width)) {
          stream += label(wrapped, margin, y, 11, PDF_FONT.bold, 0.15);
          y -= 16;
        }
        const answerLines = Math.max(1, Number(page.lines_per_prompt) || 3);
        for (let i = 0; i < answerLines && y > margin + spacing; i += 1) {
          y -= spacing;
          stream += line(margin, y, margin + width, y, 0.5, 0.85);
        }
        y -= spacing * 0.6;
      }

      // Whatever is left becomes open writing space, ruled the same way, so a
      // short prompt list does not leave half a sheet of nothing.
      if (page.rule !== 'none') {
        while (y > margin + spacing) {
          y -= spacing;
          stream += line(margin, y, margin + width, y, 0.5, 0.9);
        }
      }

      stream += footer(page.footer);
      const strip = tabStrip(page.anchor);
      const meta = addPage(stream + strip.stream, null);
      for (const link of strip.links) meta.links.push(link);
      continue;
    }

    // ---- text page: wrap, then break into as many pages as needed ---------
    const titleSize = page.title_size || (page.cover ? 30 : 18);
    const lines = [];
    for (const raw of asLines(page.lines)) {
      for (const wrapped of wrapText(raw, bodySize, usableWidth)) lines.push(wrapped);
    }

    const firstTop = PH - margin - (page.title ? titleSize + 22 : 0);
    // A contents list eats into the first page's line budget, otherwise the
    // body copy under it would run off the bottom of the sheet.
    const indexRows = Array.isArray(page.index) ? page.index.length : 0;
    const indexHeight = indexRows ? indexRows * leading * 1.7 + leading : 0;
    const linesFirstPage = Math.max(
      1, Math.floor((firstTop - indexHeight - margin) / leading));
    const linesNextPage = Math.max(1, Math.floor((PH - margin * 2) / leading));

    let cursor = 0;
    let chunkIndex = 0;
    do {
      const capacity = chunkIndex === 0 ? linesFirstPage : linesNextPage;
      const chunk = lines.slice(cursor, cursor + capacity);
      cursor += capacity;

      let stream = '';
      if (page.title && chunkIndex === 0) {
        const titleY = PH - margin - titleSize;
        stream += `BT /${PDF_FONT.bold} ${titleSize} Tf ${margin} ${titleY.toFixed(2)} Td ` +
          `(${pdfEscape(page.title)}) Tj ET\n`;
        stream += `${margin} ${(titleY - 12).toFixed(2)} m ${contentRight.toFixed(2)} ` +
          `${(titleY - 12).toFixed(2)} l 0.7 w 0.8 0.8 0.8 RG S 0 0 0 RG\n`;
      }
      if (page.subtitle && chunkIndex === 0) {
        stream += `BT /${PDF_FONT.regular} 13 Tf 0.35 0.35 0.35 rg ${margin} ` +
          `${(PH - margin - titleSize - 34).toFixed(2)} Td (${pdfEscape(page.subtitle)}) Tj ET 0 0 0 rg\n`;
      }
      let startY = (chunkIndex === 0 ? firstTop : PH - margin) -
        (page.subtitle && chunkIndex === 0 ? 26 : 0);

      // A clickable contents list, drawn above the body copy on the first page.
      const pageLinks = [];
      if (chunkIndex === 0 && Array.isArray(page.index) && page.index.length) {
        // The subtitle sits only 14pt above the body baseline, which put the
        // first contents row hard against it. A row is a tap target, so it
        // gets a clear line of its own.
        if (page.subtitle) startY -= leading;
        const block = indexBlock(page.index, startY);
        stream += block.stream;
        for (const link of block.links) pageLinks.push(link);
        startY -= page.index.length * leading * 1.7 + leading;
      }

      if (chunk.length) {
        stream += `BT /${PDF_FONT.regular} ${bodySize} Tf ${leading} TL ` +
          `${margin} ${startY.toFixed(2)} Td\n`;
        for (const line of chunk) stream += `(${pdfEscape(line)}) Tj T*\n`;
        stream += 'ET\n';
      }
      stream += footer(page.footer);
      const strip = tabStrip(page.anchor);
      const meta = addPage(stream + strip.stream, null);
      for (const link of pageLinks) meta.links.push(link);
      for (const link of strip.links) meta.links.push(link);
      chunkIndex += 1;
    } while (cursor < lines.length);
  }

  if (!pageIds.length) {
    addPage(`BT /${PDF_FONT.regular} 12 Tf 56 780 Td (Empty document) Tj ET\n`, null);
  }

  // ---- resolve links, then serialise the reserved page objects ------------
  // A link whose anchor never appeared is dropped rather than pointing
  // somewhere arbitrary: a dead tab is worse than a plain one.
  let brokenLinks = 0;
  let linkCount = 0;
  for (const meta of pageMeta) {
    const annots = [];
    for (const link of meta.links) {
      const slot = anchors[link.anchor];
      if (slot === undefined || pageIds[slot] === undefined) { brokenLinks += 1; continue; }
      const [x1, y1, x2, y2] = link.rect;
      annots.push(push(
        `<< /Type /Annot /Subtype /Link /Border [0 0 0]` +
        ` /Rect [${x1.toFixed(2)} ${y1.toFixed(2)} ${x2.toFixed(2)} ${y2.toFixed(2)}]` +
        ` /Dest [${pageIds[slot]} 0 R /XYZ null null null] >>`
      ));
      linkCount += 1;
    }
    const resources =
      `/Font << /F1 3 0 R /F2 4 0 R >>` + (meta.resources ? ' ' + meta.resources : '');
    objects[meta.id - 1] =
      `<< /Type /Page /Parent 2 0 R /MediaBox [0 0 ${PW.toFixed(2)} ${PH.toFixed(2)}]` +
      ` /Resources << ${resources} >> /Contents ${meta.contentId} 0 R` +
      (annots.length ? ` /Annots [${annots.map((id) => `${id} 0 R`).join(' ')}]` : '') +
      ` >>`;
  }

  const info = spec.info || {};
  objects[0] = '<< /Type /Catalog /Pages 2 0 R >>';
  objects[1] = `<< /Type /Pages /Count ${pageIds.length} /Kids [` +
    pageIds.map((id) => `${id} 0 R`).join(' ') + '] >>';
  objects[2] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>';
  objects[3] = '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>';
  objects[4] = '<< /Title (' + pdfEscape(info.title || 'Digital Product') + ')' +
    ' /Author (' + pdfEscape(info.author || 'AI Digital Product Factory') + ')' +
    ' /Subject (' + pdfEscape(info.subject || '') + ')' +
    ' /Keywords (' + pdfEscape(info.keywords || '') + ')' +
    ' /Creator (AI Digital Product Factory) /Producer (n8n) >>';

  // ---- serialise: header, objects, xref table, trailer --------------------
  const chunks = [];
  let offset = 0;
  const write = (value) => {
    const buf = Buffer.isBuffer(value) ? value : Buffer.from(String(value), 'latin1');
    chunks.push(buf);
    offset += buf.length;
  };

  write('%PDF-1.4\n%\xE2\xE3\xCF\xD3\n');
  const offsets = [];
  objects.forEach((obj, index) => {
    offsets[index] = offset;
    write(`${index + 1} 0 obj\n`);
    write(obj);
    write('\nendobj\n');
  });

  const xrefOffset = offset;
  write(`xref\n0 ${objects.length + 1}\n`);
  write('0000000000 65535 f \n');
  for (const o of offsets) write(`${String(o).padStart(10, '0')} 00000 n \n`);
  write(
    `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R /Info 5 0 R >>\n` +
    `startxref\n${xrefOffset}\n%%EOF\n`
  );

  return {
    buffer: Buffer.concat(chunks),
    page_count: pageIds.length,
    link_count: linkCount,
    broken_links: brokenLinks,
    dropped_index_rows: droppedRows,
  };
}

// ---------------------------------------------------------------------------
// Assemble the planner. Every structural decision is made here, in code.
// ---------------------------------------------------------------------------
const ctx = $('Gather Images').first().json;
const content = ctx.content;
const images = ctx.images;
const MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];

const year = ctx.planner_year ? Number(ctx.planner_year) : null;
const footerLabel = `${ctx.concept.product_name} - personal use`;

// ---- navigation ------------------------------------------------------------
// Twelve month tabs plus Contents is thirteen, which is the most a tab strip
// can carry legibly. The extra sections are reachable from the contents page.
const tabs = [{ label: 'Contents', anchor: 'contents' }].concat(
  MONTHS.map((name, index) => ({ label: name.slice(0, 3), anchor: `m${index + 1}` })));

const contentsRows = MONTHS.map((name, index) => ({
  label: year ? `${name} ${year}` : name,
  anchor: `m${index + 1}`,
})).concat(content.sections.map((section, index) => ({
  label: section.title,
  anchor: `s${index + 1}`,
})));

// Derived from the writer's geometry: title block, subtitle, margins and a
// 1.7x row pitch. Cross-checked by the dropped-row guard at the end.
const rowsPerContentsPage = Math.max(8, Math.floor((ctx.page_height_pt - 200) / 29));

const pages = [];

// 1. Cover: full-bleed art, then the title page.
pages.push({ type: 'image', jpeg_base64: images.cover, full_bleed: true });
pages.push({
  type: 'text', cover: true, anchor: 'cover',
  title: content.cover_title,
  subtitle: content.cover_subtitle,
  lines: ['', ctx.concept.one_liner, ''],
  footer: footerLabel,
});

// 2. How to use.
pages.push({
  type: 'text', anchor: 'welcome',
  title: content.welcome_title,
  lines: content.welcome_lines,
  footer: footerLabel,
});

// 3. Contents, spilling onto as many sheets as it needs.
for (let row = 0; row < contentsRows.length; row += rowsPerContentsPage) {
  const first = row === 0;
  pages.push({
    type: 'text',
    title: first ? 'Contents' : 'Contents (continued)',
    subtitle: first ? 'Tap a line to jump. The tabs on the right work from every page.' : undefined,
    anchor: first ? 'contents' : undefined,
    index: contentsRows.slice(row, row + rowsPerContentsPage),
    footer: footerLabel,
  });
}

// 4. Twelve months. The grid is computed, not written.
MONTHS.forEach((name, index) => {
  pages.push({
    type: 'month',
    title: year ? `${name} ${year}` : name,
    subtitle: year ? undefined : 'Undated - write your own dates',
    anchor: `m${index + 1}`,
    month_number: index + 1,
    year,
    week_starts_monday: ctx.week_starts_monday,
    side_title: 'This month',
    side_lines: content.month_prompts[index],
    footer: `${footerLabel} | ${name}`,
  });
});

// 5. Section dividers and the extra sections.
const dividers = Object.keys(images).filter((role) => role.startsWith('section_')).sort();
content.sections.forEach((section, index) => {
  // Dividers are spread evenly through the sections rather than stacked at
  // the front, so the file reads as chapters.
  const every = Math.max(1, Math.ceil(content.sections.length / (dividers.length || 1)));
  if (dividers.length && index % every === 0) {
    const art = images[dividers[Math.min(dividers.length - 1, Math.floor(index / every))]];
    if (art) pages.push({ type: 'image', jpeg_base64: art, caption: section.title,
                          footer: footerLabel });
  }
  const base = {
    anchor: `s${index + 1}`,
    title: section.title,
    subtitle: section.intro || undefined,
    footer: `${footerLabel} | ${section.title}`,
  };
  if (section.kind === 'grid') {
    pages.push({ ...base, type: 'grid', lines: section.instructions,
                 columns: section.columns, rows: section.rows,
                 row_labels: section.row_labels });
  } else {
    pages.push({ ...base, type: 'lined', lines: section.prompts,
                 lines_per_prompt: 3 });
  }
});

// 6. Licence.
pages.push({
  type: 'text', title: 'Licence',
  lines: [
    'This planner is licensed for personal use by the buyer.',
    '',
    'You may print it as often as you like for yourself and your household,',
    'and use it in any app that opens a PDF.',
    '',
    'You may not resell, redistribute, or share the file, and you may not sell',
    'anything made by exporting or tracing its pages.',
    '',
    content.credits,
  ].filter((line) => line !== undefined),
  footer: footerLabel,
});

const result = buildPdf({
  width: ctx.page_width_pt,
  height: ctx.page_height_pt,
  tabs,
  pages,
  info: {
    title: ctx.concept.product_name,
    subject: ctx.concept.niche,
    keywords: ctx.concept.keywords.join(', '),
  },
});

// The two failures that are invisible in the data and obvious to a buyer.
if (result.link_count < 12) {
  throw new Error(`Only ${result.link_count} working links in the PDF ` +
    `(${result.broken_links} dropped). The tabs are the product.`);
}
if (result.dropped_index_rows) {
  throw new Error(`${result.dropped_index_rows} contents rows did not fit on the page. ` +
    `rowsPerContentsPage (${rowsPerContentsPage}) is too high for a ${ctx.page_height_pt}pt sheet.`);
}

return [{
  json: {
    ...ctx,
    stage: 'pdf-built',
    pdf: {
      base64: result.buffer.toString('base64'),
      bytes: result.buffer.length,
      page_count: result.page_count,
      link_count: result.link_count,
    },
  },
}];

// The last gate before anything is published. Everything here is checkable
// arithmetic - no model is asked whether its own work is good.
const ctx = $('Build PDF').first().json;
const problems = [];
const pdf = ctx.pdf;

const buffer = Buffer.from(pdf.base64, 'base64');
if (buffer.slice(0, 8).toString('latin1').indexOf('%PDF-') !== 0) {
  problems.push('the PDF does not start with a PDF header');
}
if (buffer.slice(-1024).toString('latin1').indexOf('%%EOF') === -1) {
  problems.push('the PDF has no end-of-file marker');
}

// Twelve months, a contents page and a cover is 15 sheets before any extras.
if (pdf.page_count < 20) {
  problems.push(`only ${pdf.page_count} pages - a planner this thin will be returned`);
}
if (pdf.bytes < 40000) {
  problems.push(`the file is only ${pdf.bytes} bytes, which means the art is missing`);
}
if (ctx.content.sections.length < 6) {
  problems.push(`only ${ctx.content.sections.length} extra sections survived writing`);
}

// Every month must be reachable: twelve tabs on every page is the whole
// difference between this and a stack of printables.
if (pdf.link_count < ctx.pdf.page_count) {
  problems.push(`${pdf.link_count} links across ${pdf.page_count} pages - ` +
    'the tab strip is not on every page');
}

const shortPrompts = ctx.content.month_prompts
  .map((list, index) => ({ index, list }))
  .filter((m) => !m.list.length);
if (shortPrompts.length) {
  problems.push(`months with no prompt: ${shortPrompts.map((m) => m.index + 1).join(', ')}`);
}

if (problems.length) {
  throw new Error('QA rejected this planner:\n- ' + problems.join('\n- '));
}

return [{ json: { ...ctx, stage: 'qa-passed', qa: { passed: true, checks: 7 } } }];

const ctx = $('QA Gate').first().json;
const prompts = $('Prompt Library').first().json.prompts;
const c = ctx.concept;

return [{
  json: {
    ...ctx,
    stage: 'listing',
    listing_prompt: [
      `Product: ${c.product_name}`,
      `Niche: ${c.niche}`,
      `Buyer: ${c.buyer}`,
      `Their problem: ${c.buyer_problem || '(not stated)'}`,
      `They would search: ${c.search_phrase}`,
      `Keyword ideas: ${c.keywords.join(', ')}`,
      '',
      `The finished file: a ${ctx.pdf.page_count}-page undated PDF planner with`,
      `twelve tabbed month calendars, a tappable contents page, and these sections:`,
      ...ctx.content.sections.map((s) => `- ${s.title}`),
      '',
      'It is a digital download. Nothing is posted.',
      '',
      prompts.listing.contract,
    ].join('\n'),
  },
}];

// Read the assistant's reply out of an OpenAI chat completion, and fail with
// something a human can act on rather than "cannot read property of
// undefined" thirty lines later.
function agentText(response) {
  const choice = response && response.choices && response.choices[0];
  if (!choice) {
    const err = response && response.error;
    throw new Error('The model returned no choices' +
      (err ? `: ${err.message || JSON.stringify(err).slice(0, 200)}` : ''));
  }
  if (choice.finish_reason === 'length') {
    throw new Error('The model ran out of output tokens mid-answer. ' +
      'Raise max_tokens on this node, or ask for fewer sections.');
  }
  const text = choice.message && choice.message.content;
  if (!text || !String(text).trim()) throw new Error('The model returned an empty message');
  return String(text);
}

// Parse JSON that may arrive fenced in ```json ... ``` despite json_mode.
function agentJson(response, what) {
  const text = agentText(response);
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const body = (fenced ? fenced[1] : text).trim();
  try {
    return JSON.parse(body);
  } catch (e) {
    throw new Error(`${what}: the reply was not valid JSON (${e.message}). ` +
      `First 200 characters: ${body.slice(0, 200)}`);
  }
}

// Coerce a field the model may have answered with a string, an array or an
// object into an array of strings.
function asArray(value) {
  if (Array.isArray(value)) return value.map((v) => (typeof v === 'string' ? v : v));
  if (value === null || value === undefined || value === '') return [];
  if (typeof value === 'string') {
    return value.split(/[\n,]+/).map((s) => s.trim()).filter(Boolean);
  }
  if (typeof value === 'object') return Object.values(value).flatMap((v) => asArray(v));
  return [String(value)];
}

function require_(object, fields, what) {
  const missing = fields.filter((f) => {
    const v = object ? object[f] : undefined;
    return v === undefined || v === null || v === '' ||
      (Array.isArray(v) && v.length === 0);
  });
  if (missing.length) {
    throw new Error(`${what} is missing: ${missing.join(', ')}. ` +
      `Got these keys instead: ${Object.keys(object || {}).join(', ') || '(none)'}`);
  }
}

function slugify(text) {
  return String(text).toLowerCase().normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-|-$/g, '')
    .slice(0, 60);
}

// Etsy rejects a tag over 20 characters, so a long phrase is cut back to its
// last whole word rather than mid-syllable ("tech leadership resu").
function toTag(text) {
  let tag = String(text).toLowerCase().normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if (tag.length <= 20) return tag;
  tag = tag.slice(0, 20);
  const cut = tag.lastIndexOf(' ');
  return (cut > 6 ? tag.slice(0, cut) : tag).trim();
}

// Etsy rejects a bad listing after the upload, so the rules are enforced here.
const ctx = $('Build Listing Prompt').first().json;
const listing = agentJson($input.first().json, 'Listing agent');
require_(listing, ['title', 'description', 'tags'], 'The listing');

let title = String(listing.title).replace(/\s+/g, ' ').trim();
if (title.length > 140) title = title.slice(0, 140).replace(/\s+\S*$/, '');
if (/\b[A-Z]{4,}\b/.test(title)) {
  throw new Error(`The listing title shouts, which Etsy penalises: "${title}"`);
}

// Thirteen tags, each at most twenty characters, no duplicates. Topped up
// from the concept keywords rather than failing when the model is short.
const seen = new Set();
const tags = [];
for (const raw of asArray(listing.tags).concat(ctx.concept.keywords)) {
  const tag = toTag(raw);
  if (tag.length < 3 || seen.has(tag)) continue;
  seen.add(tag);
  tags.push(tag);
  if (tags.length === 13) break;
}
if (tags.length < 13) {
  throw new Error(`Only ${tags.length} usable tags after cleaning; Etsy wants 13. ` +
    `From: ${JSON.stringify(listing.tags).slice(0, 200)}`);
}

const description = String(listing.description).trim();
if (description.length < 300) {
  throw new Error(`The description is ${description.length} characters; ` +
    'a listing that short does not convert.');
}
if (/<[a-z/][^>]*>/i.test(description)) {
  throw new Error('The description contains HTML, which Etsy shows as raw tags.');
}

const cfgPrice = Number($('Planner Config').first().json.cfg.ETSY_PRICE_USD);
const modelPrice = Number(listing.price_usd);
const price = Number.isFinite(cfgPrice) && cfgPrice > 0
  ? cfgPrice
  : (Number.isFinite(modelPrice) ? Math.min(30, Math.max(5, modelPrice)) : 12);

return [{
  json: {
    ...ctx,
    stage: 'listing-ready',
    listing: {
      title,
      description: description + '\n\nThis is a digital download. Nothing will be ' +
        'posted to you. You will receive the file(s) immediately after purchase.',
      tags,
      materials: asArray(listing.materials).map((m) => toTag(m)).filter(Boolean).slice(0, 13),
      price_usd: price,
    },
  },
}];

// The listing body. Etsy wants price as a number and tags as a comma string.
const ctx = $('Parse Listing').first().json;
const cfg = $('Planner Config').first().json.cfg;

return [{
  json: {
    ...ctx,
    stage: 'publishing',
    etsy_body: {
      quantity: Number(cfg.ETSY_QUANTITY) || 999,
      title: ctx.listing.title,
      description: ctx.listing.description,
      price: Number(ctx.listing.price_usd),
      who_made: 'i_did',
      when_made: 'made_to_order',
      taxonomy_id: Number(cfg.ETSY_TAXONOMY_ID),
      listing_type: 'download',
      // A draft is reviewable before it goes live; set ETSY_LISTING_STATE to
      // 'active' once you trust the output.
      state: String(cfg.ETSY_LISTING_STATE || 'draft').toLowerCase(),
      tags: ctx.listing.tags.join(','),
      materials: ctx.listing.materials.join(','),
      should_auto_renew: false,
      is_supply: false,
      is_personalizable: false,
    },
  },
}];

// One item per upload: the shop images first, then the file itself.
const ctx = $('Prepare Etsy Draft').first().json;
const created = $input.first().json;
const listingId = created && (created.listing_id || created.results?.[0]?.listing_id);
if (!listingId) {
  throw new Error('Etsy created no listing id. Reply was: ' +
    JSON.stringify(created).slice(0, 300));
}

const uploads = [
  { kind: 'image', rank: 1, role: 'cover', b64: ctx.images.cover,
    name: `${ctx.concept.slug}-cover.jpg` },
  { kind: 'image', rank: 2, role: 'thumbnail', b64: ctx.images.thumbnail,
    name: `${ctx.concept.slug}-thumb.jpg` },
];
Object.keys(ctx.images)
  .filter((role) => role.startsWith('section_'))
  .sort()
  .forEach((role, index) => {
    uploads.push({ kind: 'image', rank: 3 + index, role, b64: ctx.images[role],
                   name: `${ctx.concept.slug}-${role}.jpg` });
  });
uploads.push({ kind: 'file', rank: 1, role: 'pdf', b64: ctx.pdf.base64,
               name: `${ctx.concept.slug}.pdf` });

return uploads.map((upload) => ({
  json: { ...upload, listing_id: listingId, run_id: ctx.run_id },
}));

// Etsy takes multipart uploads, so each item needs its bytes as binary.
const job = $input.first().json;
const buffer = Buffer.from(job.b64, 'base64');
return [{
  json: { ...job, b64: undefined },
  binary: {
    upload: await this.helpers.prepareBinaryData(
      buffer, job.name, job.kind === 'file' ? 'application/pdf' : 'image/jpeg'),
  },
}];

// One summary item: what was made, what it cost, and where it went.
const ctx = $('QA Gate').first().json;
const listing = $('Parse Listing').first().json.listing || null;
// Read the decision, not the publish branch: on a run that skipped Etsy, the
// upload nodes never executed and $('Collect Uploads') would throw.
const published = $('Start Run').first().json.publish === true;

return [{
  json: {
    run_id: ctx.run_id,
    status: 'succeeded',
    stage: 'done',
    dry_run: ctx.dry_run,
    product_name: ctx.concept.product_name,
    slug: ctx.concept.slug,
    niche: ctx.concept.niche,
    search_phrase: ctx.concept.search_phrase,
    keywords: ctx.concept.keywords,
    page_count: ctx.pdf.page_count,
    link_count: ctx.pdf.link_count,
    pdf_bytes: ctx.pdf.bytes,
    sections: ctx.content.sections.map((s) => s.title),
    listing_title: listing ? listing.title : null,
    listing_tags: listing ? listing.tags : [],
    price_usd: listing ? listing.price_usd : null,
    published,
    warnings: ctx.warnings,
    finished_at: new Date().toISOString(),
  },
}];

// The Error Trigger path. Planner Config has not run here, so nothing is read
// from it - this node only has the failure to work with.
const error = $input.first().json;
const execution = error.execution || {};
const trigger = error.trigger || {};

// n8n keeps only the tail of a long message, so the useful part goes first.
const message = String(execution.error?.message || trigger.error?.message || 'unknown error');
return [{
  json: {
    status: 'failed',
    failed_node: execution.lastNodeExecuted || null,
    message: message.slice(0, 900),
    workflow: error.workflow?.name || 'Planner Factory',
    execution_url: execution.url || null,
    failed_at: new Date().toISOString(),
  },
}];
